"""
PaloPANORAMA_single.py - BAN GOP 1 FILE DUY NHAT (PANORAMA), TU DONG SINH boi
tools/build_panorama_single.py tu 3 package DOC LAP check_rule_pan/ (tool CHECK RULE),
check_ip_pan/ (tool CHECK IP) va check_audit_pan/ (tool CHECK AUDIT) + main logic.
# BAN NAY LA BAN PANORAMA: Panorama IP + Device Group + Target Serial, object thừa kế theo chuỗi DG, rulebase lắp ráp 6 bước 0.3.

KHONG SUA TAY FILE NAY. Moi thay doi logic PHAI sua o dung file component trong
check_rule_pan/*.py, check_ip_pan/*.py hoac check_audit_pan/*.py (KHONG BAO GIO
sua nhieu package cung luc cho 1 yeu cau don le), roi chay lai
`python tools/build_panorama_single.py` de sinh lai file nay - tranh nhieu nguon
code lech nhau qua thoi gian bao tri. Kiem tra lech: `--check` (exit 1 neu lech).

Co che: 3 package check_rule_pan/, check_ip_pan/ va check_audit_pan/ duoc nen (zip)
NGUYEN VEN va nhung vao bien _EMBEDDED_PACKAGES_ZIP_B64 ben duoi (giu nguyen co che
import package chuan cua Python -> 3 tool VAN hoan toan cach ly namespace, KHONG co
rui ro trung ten bien/ham/class du ca 3 package cung dung ten file nhu core.py,
gui.py...). Luc chay, script tu giai ma + insert vao sys.path (zipimport)
TRUOC khi import - khong can giai nen ra dia, khong can file phu nao khac.

Build .exe tu file nay (can PyInstaller: pip install pyinstaller):
    pyinstaller --onefile --noconsole --name PaloPANORAMA PaloPANORAMA_single.py

Chay thu TOAN BO tinh nang khong can Panorama that:
    python testlab/run_all_features.py --auto      (xem testlab/README.md)
"""
